#include <vector>
#include <cstdio>
#define ll long long int

using namespace std;

ll n, counter;

void seive(vector<bool>& ara3) {
    fill(ara3.begin(), ara3.end(), true);
    ara3[0] = ara3[1] = false;

    for (ll i = 2; i * i <= 100001; ++i) {
        if (ara3[i]) {
            for (ll j = i * i; j <= 100001; j += i) {
                ara3[j] = false;
            }
        }
    }
}

int main(void) {
    vector<bool> ara3(100002);
    seive(ara3);

    while (cin >> n) {
        counter = 0;
        for (ll i = 1; i <= n; ++i) {
            ll j = n - i + 1;
            if (ara3[i] && ara3[j]) {
                counter++;
            }
        }
        printf("%lld\n", counter);
    }
    return 0;
}

